// ==========================================================================
// Immersive Office - Transformación y Agregación de Métricas de Empleados
// ==========================================================================
let items = $input.all();

// Si no vinieron datos del Excel (ej: ruta no encontrada), proveer dataset de fallback para tests
if (!items || items.length === 0 || !items[0].json || Object.keys(items[0].json).length === 0) {
  items = [
    { json: { ID: 1, Nombre: "Elena Navarro", Departamento: "Tecnología", Salario: 45000 } },
    { json: { ID: 2, Nombre: "Carlos Ruiz", Departamento: "Tecnología", Salario: 52000 } },
    { json: { ID: 3, Nombre: "Ana Gómez", Departamento: "Marketing", Salario: 38000 } },
    { json: { ID: 4, Nombre: "David Morales", Departamento: "Marketing", Salario: 41000 } },
    { json: { ID: 5, Nombre: "Lucía Soto", Departamento: "Ventas", Salario: 36000 } },
    { json: { ID: 6, Nombre: "Javier Sanz", Departamento: "Ventas", Salario: 48000 } }
  ];
}

const deptStats = {};
let totalNomina = 0;

for (const item of items) {
  const row = item.json;
  const dept = row.Departamento || 'Sin Asignar';
  const salario = Number(row.Salario) || 0;

  totalNomina += salario;

  if (!deptStats[dept]) {
    deptStats[dept] = {
      departamento: dept,
      total_empleados: 0,
      masa_salarial: 0,
      salario_max: 0,
      salario_min: Infinity,
      empleados: []
    };
  }

  deptStats[dept].total_empleados += 1;
  deptStats[dept].masa_salarial += salario;
  deptStats[dept].salario_max = Math.max(deptStats[dept].salario_max, salario);
  deptStats[dept].salario_min = Math.min(deptStats[dept].salario_min, salario);
  deptStats[dept].empleados.push(row.Nombre || 'Empleado');
}

// Generar filas para el nuevo reporte consolidado
const reportRows = Object.values(deptStats).map(d => ({
  json: {
    Departamento: d.departamento,
    Num_Empleados: d.total_empleados,
    Masa_Salarial_Total: d.masa_salarial,
    Salario_Promedio: Math.round(d.masa_salarial / d.total_empleados),
    Salario_Maximo: d.salario_max,
    Salario_Minimo: d.salario_min === Infinity ? 0 : d.salario_min,
    Porcentaje_Presupuesto: totalNomina > 0 ? ((d.masa_salarial / totalNomina) * 100).toFixed(2) + '%' : '0%'
  }
}));

return reportRows;
